// ===== p100 : les comptoirs d’outre-mer en 3D, bâtis avec le pack pirate de Kenney =====
const KN100={"p_structure_platform_dock": "", "p_structure": "", "p_structure_roof": "", "p_tower_complete_small": "", "p_palm_detailed_bend": "", "p_palm_straight": "", "p_crate": "", "p_chest": "", "p_cannon": "", "p_flag": "", "p_flag_pirate": "", "p_patch_sand": "", "p_rocks_sand_a": ""};
(function(){const go=()=>{if(!window.THREE||!THREE.GLTFLoader||typeof KM98==='undefined'){setTimeout(go,900);return}const L=new THREE.GLTFLoader();Object.keys(KN100).forEach(k=>{const b=atob(KN100[k]),u=new Uint8Array(b.length);for(let i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
 try{L.parse(u.buffer,'',g=>{g.scene.traverse(o=>{if(o.isMesh){o.frustumCulled=false;if(o.material&&o.material.map)o.material.map.encoding=THREE.sRGBEncoding}});const bb=new THREE.Box3().setFromObject(g.scene);KM98[k]={s:g.scene,h:Math.max(.001,bb.max.y-bb.min.y),l:Math.max(.001,bb.max.x-bb.min.x,bb.max.z-bb.min.z),y0:bb.min.y}},()=>{})}catch(e){}})};go()})();
// Dans la fiche d'un comptoir : une petite vue 3D du port. Il grandit avec ses gens et ses liens : quai, entrepôts, fortin, navires, caisses.
const CP100={};
function cp100Vue(k,host){try{if(!KM98.p_structure||!KM98.ship_med){setTimeout(()=>{if(host.isConnected)cp100Vue(k,host)},800);return}
 const c=cpInit(k),W=host.clientWidth||360,H=200,R=new THREE.WebGLRenderer({antialias:true});R.setPixelRatio(Math.min(2,devicePixelRatio));R.setSize(W,H);R.outputEncoding=THREE.sRGBEncoding;host.appendChild(R.domElement);R.domElement.style.cssText='width:100%;height:200px;border-radius:8px;display:block';
 const sc=new THREE.Scene();sc.background=new THREE.Color(0x9cc6dc);sc.fog=new THREE.Fog(0x9cc6dc,14,30);sc.add(new THREE.HemisphereLight(0xffffff,0x6a7a50,.95));const sun=new THREE.DirectionalLight(0xffffff,.7);sun.position.set(5,9,4);sc.add(sun);
 const cam=new THREE.PerspectiveCamera(40,W/H,.1,80);cam.position.set(7,5.5,9);cam.lookAt(0,0,0);
 const mer=new THREE.Mesh(new THREE.PlaneGeometry(80,80),new THREE.MeshLambertMaterial({color:0x2a7a9a}));mer.rotation.x=-Math.PI/2;sc.add(mer);
 const sable=new THREE.Mesh(new THREE.CircleGeometry(5,40),new THREE.MeshLambertMaterial({color:0xe2cf9a}));sable.rotation.x=-Math.PI/2;sable.position.set(-1.5,.02,-1.2);sc.add(sable);
 const put=(m,t,x,z,ry,long)=>{const o=km98(m,t,long);if(!o)return null;o.position.set(x,.02,z);o.rotation.y=ry||0;sc.add(o);return o};
 const taille=Math.min(6,1+Math.floor((c.gens||2)/2)+(c.lien||0));
 // un repaire pirate ou marron ne s'affiche pas dans un port tenu par une couronne : on mouille au large, dans une anse, sans pavillon
 const sec=(OUT[k]&&OUT[k].sec)||'',libre=/Libre|vides|Sultanats/.test(sec),cache=!S.voieC&&!libre;
 if(!cache){put('p_structure_platform_dock',1.6,1.4,.6,Math.PI/2,true);put('p_structure_platform_dock',1.6,2.9,.6,Math.PI/2,true)}
 for(let i=0;i<Math.min(3,taille);i++){put('p_structure',1.3,-2.6+i*1.5,-2.2,0);put('p_structure_roof',.6,-2.6+i*1.5,-2.2,0)}
 if(taille>=3)put('p_tower_complete_small',2.2,-4.2,.4,.4);
 for(let i=0;i<4+taille;i++){const a=i*1.9;put(i%2?'p_palm_detailed_bend':'p_palm_straight',1.8+(i%3)*.3,-1.5+Math.cos(a)*3.8,-1.2+Math.sin(a)*3.4,a)}
 for(let i=0;i<2+taille;i++)put(i%3?'p_crate':'p_chest',.35,.3+(i%3)*.4,-.4-Math.floor(i/3)*.4,i);
 if(taille>=4)put('p_cannon',.5,-.6,1.6,2.6);
 if(!cache)put(S.voieC?'p_flag':'p_flag_pirate',1.4,-1.2,-.6,0);
 const nav=cache?[put('ship_small',2.6,8,-6,.8,true),put('boat_row',.9,1.6,2.4,1,true)]:[put('ship_med',3.2,4.6,1.2,Math.PI/2,true),put('boat_row',.9,2.2,2.1,1,true)];if(taille>=3&&!cache)nav.push(put('ship_small',2.6,6,-5,.3,true));
 const t0=performance.now();const loop=()=>{if(CP100.stop||CP100.host!==host){R.dispose();return}if(!host.isConnected){requestAnimationFrame(loop);return}const t=(performance.now()-t0)/1000;nav.forEach((n,i)=>{if(!n)return;n.position.y=.02+Math.sin(t*1.2+i)*.05;n.rotation.z=Math.sin(t*.9+i)*.04});if(nav[2]){nav[2].position.x=6-((t*.4)%14)}
  cam.position.x=7*Math.cos(t*.05)+0;cam.position.z=9*Math.sin(.9+t*.05);cam.lookAt(-.5,0,-.5);R.render(sc,cam);requestAnimationFrame(loop)};loop()}catch(e){console.warn('cp100',e)}}
// la vue reste la même quand la fiche se redessine : on remet le même cadre à sa place
function cp100Placer(){try{const d=$('drawer');if(!d||d.hidden||onglet!=='cp'||!S||!S.cpSel){CP100.k=null;return}const k=S.cpSel;if(CP100.k!==k||!CP100.host){CP100.stop=true;CP100.k=k;const h=document.createElement('div');h.className='cp100';h.style.margin='4px 0 8px';CP100.host=h;CP100.neuf=1}
 const h=CP100.host;if(!h.isConnected){const t=d.querySelector('h3');if(t)t.after(h);else d.prepend(h)}if(CP100.neuf&&h.isConnected){CP100.neuf=0;setTimeout(()=>{CP100.stop=false;cp100Vue(k,h)},50)}}catch(e){}}
{const co=cpOuvrir;cpOuvrir=function(k){const r=co.apply(this,arguments);cp100Placer();return r}}
setInterval(cp100Placer,250);
